async fn call(
    id: u64,
    body: Vec<u8>,
    pending: &Mutex<HashMap<u64, oneshot::Sender<Reply>>>,
    tx: &mpsc::Sender<Frame>,
) -> Result<Reply, Error> {
    let (resp_tx, resp_rx) = oneshot::channel();
    pending.lock().await.insert(id, resp_tx);          // register BEFORE send
    tx.send(Frame { id, body }).await?;
    match timeout(Duration::from_secs(5), resp_rx).await {
        Ok(Ok(reply)) => Ok(reply),                    // read loop matched the id
        Ok(Err(_)) => Err(Error::NoReply),             // Sender dropped: entry removed
        Err(_) => Err(Error::Timeout),                 // late reply dropped on remove
    }
}
